(function(){const el=document.getElementById('reportTerritoryMap');if(!el||typeof L==='undefined')return;const objects=<?=json_encode($reportTerritorialObjects,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,layers=<?=json_encode($reportTerritorialLayers,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const map=L.map(el,{zoomControl:false,attributionControl:false,scrollWheelZoom:false,dragging:false,doubleClickZoom:false,keyboard:false,touchZoom:false}).setView([<?=json_encode((float)($tenant['latitude']?:-15))?>,<?=json_encode((float)($tenant['longitude']?:-52))?>],10);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(map);<?php if(!empty($tenant['geojson_delimitacao'])):?>fetch('/media/municipios/<?=$tenant['id']?>/territorio',{credentials:'same-origin'}).then(r=>r.json()).then(geo=>{const boundary=L.geoJSON(geo,{style:{color:'#df4541',weight:2,fillColor:'#176fdd',fillOpacity:.08}}).addTo(map);const b=boundary.getBounds();if(b.isValid())map.fitBounds(b,{padding:[12,12]});}).catch(()=>{});<?php endif;?>const markerIcon=layer=>StratelliTerritorialIcons.markerIcon(layer,{size:28,compact:true});objects.forEach(o=>{if(!o.geometry)return;const ld=layers.find(l=>l.id===o.camada_id),color=ld?.cor||'#176fdd';L.geoJSON({type:'Feature',properties:{},geometry:o.geometry},{style:{color,weight:3,fillColor:color,fillOpacity:.23},pointToLayer:(f,ll)=>L.marker(ll,{icon:markerIcon(ld),interactive:false})}).addTo(map)});setTimeout(()=>map.invalidateSize(),100);})();
